import pandas as pd,numpy as np,json,pathlib
r=pathlib.Path('historical-capture/shareholder_frequency');out=pathlib.Path(__file__).resolve().parent;raw=pd.DataFrame(json.load(open(r/'raw.json')));latest=pd.DataFrame(json.load(open(r/'latest.json')));old=set(pd.read_csv(r/'qualified_453.csv',dtype={'code':str}).code);candidate=set(pd.read_csv(out.parent/'qualified_982.csv',dtype={'code':str}).code)
for c in ['END_DATE','HOLD_NOTICE_DATE']:raw[c]=pd.to_datetime(raw[c]).dt.normalize()
lo=pd.Timestamp('2026-08-01');hi=pd.Timestamp('2026-10-31');listed=set(latest.loc[~latest.SECURITY_NAME_ABBR.str.contains('退'),'SECURITY_CODE']);d=raw[raw.SECURITY_CODE.isin(listed)&raw.SECURITY_CODE.str.startswith(('0','3','6','8','92','43'))&raw.HOLD_NOTICE_DATE.between(lo,hi)].copy()
def run(clean):
 x=d[d.END_DATE<=d.HOLD_NOTICE_DATE].copy() if clean else d.copy();x=x.sort_values(['SECURITY_CODE','END_DATE','HOLD_NOTICE_DATE']).drop_duplicates(['SECURITY_CODE','END_DATE']);x=x.sort_values('END_DATE').groupby(['SECURITY_CODE','HOLD_NOTICE_DATE'],as_index=False).last().sort_values(['SECURITY_CODE','HOLD_NOTICE_DATE']);rows=[]
 for code,g in x.groupby('SECURITY_CODE'):
  frontier=g.END_DATE.cummax().shift();z=g[g.END_DATE>frontier.fillna(pd.Timestamp('1900-01-01'))];dates=z.HOLD_NOTICE_DATE;gaps=dates.diff().dt.days.dropna();rows.append({'code':code,'events':len(z),'span':(dates.iloc[-1]-dates.iloc[0]).days,'mean_gap':gaps.mean(),'max_gap':gaps.max(),'last_gap':(hi-dates.iloc[-1]).days,'first_gap':(dates.iloc[0]-lo).days})
 p=pd.DataFrame(rows);p['qualifies']=(p.events>=3)&(p.span>=60)&(p.mean_gap<=30)&(p.last_gap<=30);return p
p=run(False);q=run(True);s0=set(p.loc[p.qualifies,'code']);s1=set(q.loc[q.qualifies,'code']);selected=p[p.qualifies];s={'raw_rows':len(raw),'source_dates_outside_window':int((~raw.HOLD_NOTICE_DATE.between(lo,hi)).sum()),'eligible_source_rows':len(d),'raw_negative_lag':int((raw.END_DATE>raw.HOLD_NOTICE_DATE).sum()),'eligible_negative_lag':int((d.END_DATE>d.HOLD_NOTICE_DATE).sum()),'replicated_pool':len(s0),'candidate_missing':sorted(s0-candidate),'candidate_extra':sorted(candidate-s0),'old453_not_in_new':sorted(old-s0),'new_additions':len(s0-old),'pool_after_negative_lag_clean':len(s1),'removed_by_negative_lag_clean':sorted(s0-s1),'added_by_negative_lag_clean':sorted(s1-s0),'old453_lost_after_clean':sorted(old-s1),'boundary_counts':{'events_exact3':int((selected.events==3).sum()),'span_exact60':int((selected.span==60).sum()),'mean_exact30':int((selected.mean_gap==30).sum()),'last_gap_exact30':int((selected.last_gap==30).sum()),'internal_gap_over30':int((selected.max_gap>30).sum()),'first_gap_over30':int((selected.first_gap>30).sum())},'six_event_control':int((p.qualifies&(p.events>=6)).sum()),'max_gap_le30_control':int((p.qualifies&(p.max_gap<=30)).sum())};p.to_csv(out/'independent_pool_metrics.csv',index=False);q.to_csv(out/'negative_lag_clean_metrics.csv',index=False);(out/'pool_audit.json').write_text(json.dumps(s,indent=2));print(json.dumps(s,indent=2))
